{"implementation":"import math
from fractions import Fraction
from numbers import Real


def solve(case):
    if not isinstance(case, dict):
        raise ValueError("case must be an object")
    if "segments" not in case or "budget" not in case:
        raise ValueError("case requires segments and budget")

    segments = case["segments"]
    budget = case["budget"]
    if not isinstance(segments, list):
        raise ValueError("segments must be a list")
    if isinstance(budget, bool) or not isinstance(budget, int):
        raise ValueError("budget must be an integer")
    if budget < 0:
        raise ValueError("budget must be nonnegative")

    names = []
    importances = []
    allocations = []
    capacities = []

    for index, segment in enumerate(segments):
        if not isinstance(segment, dict):
            raise ValueError("each segment must be an object")
        required = ("name", "importance", "minimum", "capacity")
        if any(field not in segment for field in required):
            raise ValueError("each segment requires name, importance, minimum, and capacity")

        name = segment["name"]
        importance = segment["importance"]
        minimum = segment["minimum"]
        capacity = segment["capacity"]

        if not isinstance(name, str) or not name:
            raise ValueError("segment names must be nonempty strings")
        if name in names:
            raise ValueError("segment names must be unique")
        if isinstance(importance, bool) or not isinstance(importance, Real):
            raise ValueError("importance must be a finite number")
        if not math.isfinite(importance) or importance < 0:
            raise ValueError("importance must be a finite nonnegative number")
        if isinstance(minimum, bool) or not isinstance(minimum, int) or minimum < 0:
            raise ValueError("minimum must be a nonnegative integer")
        if isinstance(capacity, bool) or not isinstance(capacity, int) or capacity < minimum:
            raise ValueError("capacity must be an integer at least as large as minimum")

        names.append(name)
        importances.append(Fraction(importance))
        allocations.append(minimum)
        capacities.append(capacity)

    minimum_total = sum(allocations)
    capacity_total = sum(capacities)
    if budget < minimum_total or budget > capacity_total:
        raise ValueError("budget is infeasible")

    while sum(allocations) < budget:
        best = None
        for index in range(len(allocations)):
            if allocations[index] >= capacities[index]:
                continue
            if best is None:
                best = index
                continue
            left = importances[index] * (allocations[best] + 1)
            right = importances[best] * (allocations[index] + 1)
            if left > right:
                best = index
        if best is None:
            raise ValueError("budget is infeasible")
        allocations[best] += 1

    name_mapping = {names[index]: allocations[index] for index in range(len(names))}
    return {
        "allocations": allocations,
        "name_mapping": name_mapping,
        "conserved_total": sum(allocations),
    }
"}
